stages.sampleAnswer:
- Package: { id, origin, destination, size, weight, createdAt }
- Courier: { id, name, phone, currentLocation, isAvailable }
- Delivery: { id, packageId, courierId, status, assignedAt, pickedUpAt, deliveredAt }
- Location: { courierId, lat, lng, timestamp }
- DeliveryStatus: enumeration (pending, assigned, picked_up, delivered)

POST /deliveries
  body: { originAddress, destinationAddress, packageSize, phone }
  → 201 { deliveryId, estimatedPickupTime }

GET /deliveries/:id
  → 200 { id, status, courierLocation, estimatedArrival }

GET /deliveries/available
  query: { courierId }
  → 200 { deliveries: [...] }

POST /deliveries/:id/accept
  body: { courierId }
  → 200 { accepted }

POST /deliveries/:id/status
  body: { status: 'picked_up' | 'delivered', timestamp }
  → 200 { success }
